<script setup lang="ts">
import type { ApiEnvelope } from '~/types/api'
import type { Page, Payment, Subscription } from '~/types/billing'
import { money, billingDate } from '~/utils/billing'
definePageMeta({layout:'admin',middleware:'superadmin'})
const { request }=useApi()
const {rows,pagination,pending,error,refresh,page,message,failure,saving,mutate}=await useManagement<Payment>('payments')
const editing=ref(false), voiding=ref<Payment|null>(null), subscriptions=ref<Subscription[]>([]), customerSearch=ref('')
const form=reactive({subscription_id:0,amount:'',method:'bank_transfer',reference:'',paid_at:new Date().toISOString().slice(0,16),notes:''})
async function find(){try{subscriptions.value=(await request<ApiEnvelope<Page<Subscription>>>('management/subscriptions',{query:{search:customerSearch.value}})).data.data.filter(s=>s.provider==='manual')}catch{failure.value='Unable to find subscriptions.'}}
async function record(){if(await mutate('management/payments',{...form,amount:Math.round(Number(form.amount)*100)}))editing.value=false}
</script>
<template><div><div class="flex justify-between"><div><p class="eyebrow">Financial records</p><h1 class="page-title mt-2">Manual payments</h1><p class="mt-2 text-text-secondary">Record payments received outside Stripe. Stripe receipts and refunds stay in Stripe.</p></div><button class="btn-primary" @click="editing=true;failure='';find()">+ Record payment</button></div><p v-if="message" class="mt-5 bg-success-bg p-3 text-success" role="status">{{ message }}</p><p v-if="failure && !editing" class="mt-5 text-danger" role="alert">{{ failure }}</p><div class="surface mt-8 overflow-hidden"><LoadingState v-if="pending"/><p v-else-if="error" class="p-8" role="alert">Unable to load payments. <button class="text-brand" @click="refresh()">Retry</button></p><div v-else class="overflow-x-auto"><table class="admin-table"><thead><tr><th>Reference</th><th>Customer</th><th>Amount</th><th>Method</th><th>Received</th><th>Status</th><th>Action</th></tr></thead><tbody><tr v-for="payment in rows" :key="payment.id"><td class="font-medium">{{ payment.reference }}</td><td>{{ payment.subscription?.user?.email }}</td><td>{{ money(payment.amount,payment.currency) }}</td><td>{{ payment.method.replaceAll('_',' ') }}</td><td>{{ billingDate(payment.paid_at) }}</td><td><span :class="payment.status==='paid'?'badge-success':'badge-warning'">{{ payment.status }}</span></td><td><button v-if="payment.status==='paid'" class="text-danger" @click="voiding=payment">Void record</button></td></tr><tr v-if="!rows.length"><td colspan="7" class="py-12 text-center">No manual payments have been recorded.</td></tr></tbody></table></div><AdminPagination v-if="pagination" :current="pagination.current_page" :last="pagination.last_page" :total="pagination.total" :pending="pending" @change="page=$event"/></div><AdminDialog v-if="editing" title="Record a received payment" @close="editing=false"><form class="grid gap-4" @submit.prevent="record"><div class="flex gap-2"><input v-model="customerSearch" class="input" placeholder="Find customer by email" aria-label="Find subscription"><button type="button" class="btn-secondary" @click="find">Find</button></div><label class="label">Subscription<select v-model.number="form.subscription_id" class="input mt-2" required><option :value="0" disabled>Select subscription</option><option v-for="subscription in subscriptions" :key="subscription.id" :value="subscription.id">#{{ subscription.id }} · {{ subscription.user?.email }} · {{ subscription.currency }}</option></select></label><label class="label">Amount received<input v-model="form.amount" class="input mt-2" type="number" step="0.01" min="0.01" required></label><label class="label">Payment method<select v-model="form.method" class="input mt-2"><option value="bank_transfer">Bank transfer</option><option value="cash">Cash</option><option value="mobile_banking">Mobile banking</option><option value="other">Other</option></select></label><label class="label">Unique transaction reference<input v-model="form.reference" class="input mt-2" maxlength="150" required></label><label class="label">Received at<input v-model="form.paid_at" class="input mt-2" type="datetime-local" required></label><label class="label">Internal notes<textarea v-model="form.notes" class="input mt-2" maxlength="2000"/></label><p v-if="failure" class="text-danger" role="alert">{{ failure }}</p><button class="btn-primary" :disabled="saving">{{ saving?'Recording…':'Record payment' }}</button></form></AdminDialog><AdminDialog v-if="voiding" title="Void payment record?" @close="voiding=null"><p>This marks {{ voiding.reference }} as void and retains the audit history. No refund or bank transaction will occur.</p><button class="btn-danger mt-6" :disabled="saving" @click="async()=>{if(await mutate(`management/payments/${voiding!.id}/void`))voiding=null}">Confirm void</button></AdminDialog></div></template>
